  if(f) h += '<span class="twh-ff twh-ff-' + ffsCls(f.ff) + (f.upd && now() - f.upd > FFS_OLD ? ' twh-ffold' : '') + '" title="' + t + '">' + ffsFmt(f.ff) + '</span>';
