const STAY_SHOW = 15 * 60, GO_SHOW = 5 * 60;
const STAY_RE = /\bturtle\b|\bstay\s+in\s+(?:the\s+)?hosp(?:ital)?\b|\bstay\s+hosp\b/i;
const callOn = k => get(k, true);
